-- HalalNeo content expansion batch (Sept 2026)
-- 2 market guides (market_guides) + 8 KB article expansions (knowledge_base)
-- Research: halalfocus.com + Daily Sun (Jan 2026, IF/BSTI dispute, IF since 2007, 276 companies / 600 products / 45 countries, JAKIM recognition),
-- TBS News (Jul 2026, $943M exports, Saudi non-recognition reports), Daily Star (Jul 2025, BSTI National Halal Lab),
-- USDA GAIN EG2025-0008 (dairy exemption Mar 2025), ChemLinked Egypt food regulations (ES 4249, GOVS, NFSA, Nafeza ACI),
-- iseghalal.com (sole-entity claim, WTO G/TBT/N/EGY/313), foodmanufacture.co.uk (UK dairy GBP26M 2024),
-- MPI NZ (halal assurance system, AHO list Jun 2026, FIANZ since 1984), DAFF Australia (AGAHP est 1997, AIO list Jul 2026),
-- HAK english.hak.gov.tr (Law 7060, SMIIC, IFHAB), HAK France page (Paris/Lyon/Evry mosques, ~50 bodies),
-- GSO gso.org.sa (G-mark), ITMAD (ECAS 1-yr, EQM 3-yr, SABER PCoC/SCoC), halal.gov.my (MYeHALAL),
-- halal.muis.gov.sg (e-Service), ptsp.halal.go.id (SIHALAL), halal.or.th + halal.co.th + THIC (CICOT e-services, Or.2/Or.17/Or.18),
-- USCIRF 2025 (Egypt ~111.2M, ~90% Muslim), BBS census 2022 (Bangladesh 91.04% Muslim).
-- Where figures are unverifiable, copy hedges with "confirm with ..." phrasing.
-- NOTE: market_guides status='published' follows drizzle/week1_content.sql + drizzle/week2_content.sql convention.

INSERT INTO "market_guides" ("slug","country","flag","region","muslim_population","total_population","market_size_usd","mandate_status","mandatory_since","certifying_bodies","import_requirements","standard_basis","certificate_validity","estimated_cost_usd","processing_time","key_insights","opportunities","challenges","summary","meta_title","meta_description","keywords","status","created_at","updated_at") VALUES ('bangladesh','Bangladesh','🇧🇩','South Asia','~150 million (about 91% of residents, 2022 census)','~170 million','$1B+ (halal exports reached $988.6M in FY24-25; consolidated domestic market size unpublished — confirm with EPB)','voluntary',NULL,'[]','["No blanket halal import mandate — but goods marketed as halal need certification and the associated logo under the Islamic Foundation policy","Dual domestic system: Islamic Foundation (IF) and BSTI issue halal certificates independently — exporters typically certify via JAKIM/MUI-recognised bodies for destination-market acceptance","BSTI product-standards testing underneath: National Halal Laboratory opened July 2025 with PCR-based porcine-derivative testing","Bangla/English labelling per BSTI labelling rules — confirm current language and halal-logo-use requirements with the importer","Meat and poultry: confirm slaughter-certification paperwork and establishment approval with the importer before shipment"]','BDS CAC GL 24:2003 (halal general guidelines); BDS 1813:2009 (halal food production/handling); OIC/SMIIC membership since 2022','Typically 1 year (confirm with the issuing body)','IF application fees reported from around Tk 5,000 for small plants (schedule-dependent; confirm the current fee schedule before budgeting)','Typically several weeks to a few months depending on documentation readiness (confirm with IF or BSTI)','["Fourth-largest Muslim population in the world — about 150 million Muslims, roughly 91% of residents","Halal exports hit $988.6M in FY24-25 (mostly agro-processed) against a multi-trillion-dollar global market — share still negligible","Islamic Foundation certifying since 2007: 276 companies and 600 products across 45 countries as of January 2026, with JAKIM recognition","BSTI opened the National Halal Laboratory in July 2025 and joined OIC/SMIIC in 2022 — technical capacity is catching up","Live reform debate: exporters and EPB are pushing a single internationally recognised halal authority to end dual certification"]','["Agro-processed exports (spices, biscuits, beverages, frozen foods) already move — PRAN-scale players show the route","JAKIM-linked acceptance gives Bangladeshi goods a path into Malaysia, Brunei, the Middle East and the EU — confirm scope per shipment","Adjacent sectors barely tapped: cosmetics, pharmaceuticals, modest fashion and Islamic finance flagged by EPB as next waves","First-mover edge: only around 300 certified manufacturers nationally, so compliant exporters stand out fast"]','["Dual IF/BSTI certification inflates cost and weakens brand credibility abroad — budget for both until the system unifies","Neither domestic body is reported as recognised by Saudi accreditation — Gulf-bound goods may need third-country certification","Some mandated tests (heavy metals, pesticide residues) are reported as unavailable domestically — confirm lab routing early","No formal mutual-recognition agreements reported with major authorities — expect repeated audits per destination market"]','A giant Muslim consumer base whose halal export engine is still warming up. Bangladesh offers low-cost agro-processed supply, but exporters must navigate a dual certification system and lean on JAKIM-recognised routes until a single authority emerges.',NULL,NULL,NULL,'published',1789500000,1789500000);

INSERT INTO "market_guides" ("slug","country","flag","region","muslim_population","total_population","market_size_usd","mandate_status","mandatory_since","certifying_bodies","import_requirements","standard_basis","certificate_validity","estimated_cost_usd","processing_time","key_insights","opportunities","challenges","summary","meta_title","meta_description","keywords","status","created_at","updated_at") VALUES ('egypt','Egypt','🇪🇬','Middle East','~100 million (about 90% of residents)','~115 million','$20B+ (domestic halal food consumption, estimate — confirm with official trade data before quoting)','mandatory','Meat and poultry (ES 4249; enforced via GOVS import permits)', '[]','["Halal certificate mandatory for meat and poultry imports — IS EG Halal is the sole entity authorised to certify foreign products for Egypt","GOVS import permit requires the ES 4249 halal certificate; confirm whether Egyptian Customs asks for it separately at port clearance","Milk and dairy exempt from halal certification since March 2025 (WTO notification G/TBT/N/EGY/313/Add.9) — confirm the current scope before shipping","NFSA importer licensing and facility registration plus Nafeza ACI filing (ACID number at least 48 hours before sailing)","Arabic labelling per NFSA rules; special dietary foods need product registration (up to 60 days, 5-year validity)"]','ES 4249 (halal requirements for imports); NFSA food safety framework; GSO texts where adopted — confirm the applicable edition per shipment','Per-shipment halal certificates for meat and poultry (confirm validity practice with IS EG Halal)','Certification fees are set per shipment — confirm the current IS EG Halal schedule before budgeting; reported levels have drawn trade scrutiny','IS EG Halal registration reported at 3–7 working days plus audit scheduling and supervised production — confirm current timelines','["Around 100 million Muslims — the largest consumer market in the Arab world and a historic price-setter for halal meat","Single-gatekeeper model: one authorised halal entity for foreign meat and poultry, layered over GOVS permits and NFSA controls","Dairy gate lifted in March 2025 after years of WTO notices — the UK alone sees GBP 250M in five-year export upside","Egypt–Brazil pre-listing protocol (February 2024) shows the direction: approved slaughterhouses plus accredited halal certification","UK dairy exports ran about GBP 26M in 2024 — established foreign supply chains already clear Egyptian ports daily"]','["Meat and poultry supply gap: a 100M+ Muslim market with mandatory certification rewards compliant slaughterhouses","Dairy exporters now enter without halal overhead — cheese, butter and powders face a simplified file","Processed and special-dietary foods via NFSA registration open a second, less crowded door","Suez-adjacent logistics let one Egyptian foothold serve North Africa and the Levant — confirm re-export paperwork per market"]','["Sole-entity certification concentrates bottleneck and pricing risk — build lead time and confirm fees in writing","Three gates, three logics: GOVS (veterinary), NFSA (food safety), Customs (clearance) — a pass at one is not a pass at all","Nafeza ACI discipline is unforgiving: no ACID number before sailing means blocked release on arrival","Regulatory scope shifts (the dairy saga ran through nine WTO addenda) — re-verify requirements before every season"]','The Arab world''s largest halal consumer market, gated by a distinctive single-entity meat certification system. Exporters who master the GOVS–NFSA–Nafeza sequence find deep, repeat demand; those who improvise paperwork do not clear the port.',NULL,NULL,NULL,'published',1789500000,1789500000);

UPDATE knowledge_base SET body='New Zealand runs one of the world''s tightest export-side halal systems: nothing about it is left to the abattoir''s word alone. The Ministry for Primary Industries (MPI) sets the rules, independent Approved Halal Organisations (AHOs) audit and certify against them, and each destination market''s import conditions sit on top. For buyers of lamb, beef, venison and dairy, that chain is what makes a New Zealand halal certificate bankable. Related: [Malaysia market guide](/market-guides/malaysia) and [MUIS certifier profile](/certifying-bodies/muis).

## FIANZ: the main certifier, verified

The Federation of Islamic Associations of New Zealand (FIANZ) is the country''s long-standing Islamic umbrella body, and its certification arm FIANZ Halal Limited states it has provided halal certification since 1984. It describes itself as an MPI-approved AHO, and MPI''s published AHO list (June 2026 edition) confirms FIANZ Halal Limited with broad dairy, poultry and red-meat coverage across the Gulf, Southeast Asia and North Africa. MPI''s list also records FIANZ as specifically approved by Singapore''s MUIS, Thailand''s CICOT, Indonesia''s BPJPH, Saudi Arabia''s SFDA and Turkiye''s HAK for defined product scopes. When a supplier names FIANZ on a certificate, check that the destination market appears in its current MPI listing — approval is market-by-market, not blanket.

## How the MPI export system works

Every halal-exporting premises needs a documented halal programme recording which markets it can serve and how its halal operation runs. An AHO approves that programme and issues halal certificates through MPI''s Animal Products E-cert system; the premises must separately register with MPI as an approved halal establishment. Exporters then check the Overseas Market Access Requirements (OMARs) for the destination — OMARs for halal products are password-protected, so buyers should ask suppliers which OMAR conditions the shipment was certified against. Two certificate types may apply: a halal certificate from the AHO, a sanitary certificate from MPI, or both. MPI''s framework covers beef, sheep, goat, deer and poultry species, plus qualifying mixed foods.

## Beyond FIANZ: the wider AHO bench

MPI lists multiple AHOs, and the bench matters because different markets recognise different bodies. The June 2026 list includes Halal Conformity Services, the New Zealand Islamic Development Trust (NZIDT, itself HAK-accredited for product certification), New Zealand Global Halal Assurance, and IS EG Halal New Zealand — the local arm of Egypt''s sole authorised halal entity, which is relevant for meat exporters targeting Egypt. NZIDT and FIANZ both carry MUIS and CICOT approvals for Singapore and Thailand; FIANZ additionally carries BPJPH approval for Indonesian food and beverage lines. For Gulf destinations, confirm the AHO appears against that specific country — listings for Saudi Arabia, the UAE, Qatar, Bahrain and Oman differ by organisation and product type.

## What buyers should verify before ordering

First, get the full certificate, not a cropped logo: business name, certificate number, scope, and expiry must be legible. Second, match scope to the purchase — species, cuts, dairy lines and the production site must all appear. Third, confirm the AHO''s MPI listing covers the destination market for that product type, and cross-check any destination-specific approval (MUIS, CICOT, BPJPH, SFDA) the buyer''s own market requires. Fourth, ask whether stunning or mechanical-slaughter methods were used where the buyer''s market is strict on method — New Zealand plants commonly stun, and some Gulf buyers differentiate. Fifth, run the certificate through our [verification walkthrough](/verify) and keep the halal file with the sanitary and label files — port holds still follow when the programme market list and the shipped destination disagree.

## Export relevance in one paragraph

New Zealand is a price-making exporter of halal lamb, beef and dairy into Southeast Asia and the Gulf, and its government-backed assurance framework is why import authorities from Kuala Lumpur to Riyadh accept its paperwork with comparatively little friction. Certification is export-only — MPI standards do not govern domestic halal — so buyers should always read a New Zealand halal certificate as an export document tied to named markets, not a general quality badge. Confirm the current AHO list with MPI before each buying season, because country listings and accreditations rotate.', updated_at=1789500000 WHERE slug='new-zealand-halal';

UPDATE knowledge_base SET body='Australia is one of the few non-Muslim countries with legislation specifically governing halal meat for export — and that is both the opportunity and the trap for buyers. The export chain is tightly regulated; everything else with a halal logo in Australia is a private claim. Knowing which world your product sits in determines which checks apply. For market context see our [Malaysia market guide](/market-guides/malaysia) and the [JAKIM certifier profile](/certifying-bodies/jakim).

## The AGAHP system: government control, religious delivery

The Australian Government Authorised Halal Program (AGAHP), run by the Department of Agriculture, Fisheries and Forestry (DAFF), regulates all halal red meat and red meat products intended for export. Established in 1997, it is a three-way partnership: DAFF holds legislative control and market access, Approved Islamic Organisations (AIOs) deliver religious oversight, and export-registered establishments guarantee hygiene, integrity, traceability and animal welfare. Facilities and AIOs must both comply with AGAHP, and only compliant product is eligible for an official Australian halal certificate. The legal anchor is the Export Control (Meat and Meat Products) Rules 2021.

## The AIO list: your first verification stop

DAFF publishes the list of recognised Islamic bodies for halal red-meat certification, current as of 8 July 2026, with market-by-market recognition columns for Indonesia, Malaysia, Saudi Arabia, Singapore, the UAE, Qatar, Bahrain, Turkiye and Egypt. Names on the current list include the Supreme Islamic Council of Halal Meat in Australia, Australian Halal Development and Accreditation, Australian Halal Authority and Advisers, and several state-based bodies — but the list rotates, so always check the live DAFF page rather than any article''s copy. Two footnotes matter commercially: Egypt requires certification from Halal Al-Qahirah for listed goods including red meat, so confirm the Egypt meat page on MICOR before contracting; and DAFF points all market-specific detail at its Manual of Importing Country Requirements (MICOR), which buyers should read alongside the certificate.

## NHASA in context

The National Halal Certification Authority (NHASA, operating since 2018) holds a DAFF approved arrangement for halal red meat and red meat products for export, making it an AIO for that scope. It publishes approvals from Indonesia''s BPJPH, Thailand''s CICOT and Singapore''s MUIS for defined scopes, with JAKIM recognition described as in progress — verify before relying on it. NHASA''s positioning illustrates the broader market: alongside older bodies such as AFIC (certifying since 1974, when a Saudi delegation first recommended it) and the large Victoria-based certifiers, newer AIOs compete on export-market coverage. For buyers the lesson is uniform — an AIO''s value is exactly the set of destination markets that currently recognise it, nothing more.

## Export versus domestic: the split that catches buyers out

AGAHP covers red meat and meat products for export only. Halal claims on products sold inside Australia — packaged foods, restaurants, cosmetics — are certified entirely by private organisations with no federal regulator checking the claim, and there is no government halal logo to fall back on. History explains the split: a 1981 meat-substitution scandal triggered a Royal Commission, and the policy response tightened the export chain while leaving domestic labelling unregulated. So a halal logo on an Australian retail pack answers a different question than an AGAHP export certificate. Name the certifier on the pack, then check that certifier''s own current client list — and for export consignments, insist on the AIO export certificate, not the domestic logo.

## Buyer checks before contracting Australian meat

Confirm the AIO appears on DAFF''s current recognised-bodies list for your destination market and product type. Read the MICOR page for that market — slaughter, stunning and documentation conditions vary. Check certificate scope, site, species and expiry against the contracted goods, and confirm slaughter-method paperwork where your market differentiates. For processed or non-meat lines, verify the private certifier''s standing directly, since AGAHP does not cover them. And keep the full file — halal certificate, health certificate, label approvals — together through clearance, because Gulf and Southeast Asian ports check the set, not the single page.', updated_at=1789500000 WHERE slug='australia-nhasa';

UPDATE knowledge_base SET body='Europe has no EU-wide halal regulation, no single halal standard, and no single accreditation ladder — and that fragmentation is the single most important fact for buyers. Each country runs its own mix of private certifiers, mosque-linked bodies and retailer schemes, while export recognition depends on whether the destination authority knows the certifier''s name. For Gulf destinations see our [UAE market guide](/market-guides/uae) and [Saudi Arabia market guide](/market-guides/saudi-arabia).

## The United Kingdom: HFA, HMC and the stunning divide

The UK hosts several independent certifiers with genuinely different standards. The Halal Food Authority (HFA), established 1994, is the longest-standing mainstream body, certifying meat, poultry, processed foods and food service with acceptance of reversible stunning and mechanical slaughter for poultry. The Halal Monitoring Committee (HMC), founded the same year in Leicester, applies the strictest mainstream standard: hand slaughter only, with documented proof the animal was alive at the cut where any stunning is used. Halal Certification Europe (HCE, operating since 1992) works across the UK and EU from a Codex Alimentarius baseline and carries recognition from several Gulf import authorities, which makes it the natural pick for UK manufacturers exporting to the Middle East. Smaller and regional schemes, plus mosque-linked arrangements, sit alongside them — and the UK government mandates none of them.

## France: three mosques, dozens of bodies

France holds Western Europe''s largest Muslim population — about 5.7 million people, nearly 10% of residents — with a halal market estimated at 5.5 billion euros, of which 4.5 billion is halal food. There is no compulsory halal certification legislation; around fifty organisations issue certificates, including the Paris, Lyon and Evry mosques, each applying independent criteria and striking its own arrangements with foreign exporters. Exporters can conclude specific agreements with any of the three mosques, but a certificate accepted by one is not automatically accepted by another — confirm which body the buyer''s customers actually trust. Retail halal sales keep growing (past 300 million euros in 2023).

## Retailer-specific requirements: the real gatekeepers

In the absence of state standards, large buyers write their own. The Nando''s UK case is instructive: some branches operate under HMC certification and others under HFA, with a branch lookup so customers can check which standard applies. The pattern repeats across supermarkets and food-service chains — the retailer''s technical team decides which certifiers and slaughter methods are acceptable. Exporters should therefore qualify the certifier with the retail customer before production, get the approved-body list in writing, and print only the logos the contract names. A certificate valid in one retail chain can be worthless in the next.

## How exporters should navigate the patchwork

First, fix the destination: a UK pack bound for the Gulf needs a Gulf-recognised certifier (HCE is the commonly cited route), while the same pack for domestic UK sale needs whatever the retail customer mandates. Second, settle the stunning question early — HMC-style hand-slaughter-only product and HFA-style stunned product are different goods in the eyes of strict buyers, and switching mid-contract breaks trust. Third, keep slaughter-method evidence (stun parameters, survival attestations, slaughterman credentials) inside the technical file, because auditors for strict markets ask for it. Fourth, verify every certificate through our [verification walkthrough](/verify) and diary renewals — European certificates typically run one to three years, and an expired logo on shipped stock is a port-hold waiting to happen.

## When Europe is the source, not the destination

European halal-certified ingredients — dairy powders, gelatin alternatives, enzymes, flavourings — flow into Gulf and Southeast Asian factories, where the destination authority checks the European certifier''s recognition status. Before specifying a European halal ingredient for a JAKIM, MUIS or SFDA filing, confirm the issuing body sits on that authority''s recognised list for the relevant category. Recognition is category-by-category and rotates; a body recognised for meat may not be recognised for ingredients. Confirm with the authority, lock the approved certifier into the supplier agreement, and re-check annually.', updated_at=1789500000 WHERE slug='europe-halal-certification';

UPDATE knowledge_base SET body='The most common misunderstanding about Turkiye''s halal system is a category error: HAK does not certify products. The Halal Accreditation Agency (HAK) accredits the bodies that certify — it audits the auditors under Law 7060, which names it the only institution authorised to accredit halal conformity-assessment bodies in Turkiye. Exporters therefore never apply to HAK for a product certificate; they choose a HAK-accredited certifier and let the accreditation do the trust work downstream. For Gulf market context see our [Saudi Arabia market guide](/market-guides/saudi-arabia).

## What accreditation actually means

Accreditation answers a different question than certification. A certifier says this product is halal; HAK says this certifier is competent to make that call. HAK evaluates management systems, auditor competence, testing arrangements and impartiality against OIC/SMIIC standards, conducts on-site assessments, and lists accredited bodies publicly. HAK itself states plainly that it issues no halal certificates and that uncertified product is merely uncertified, not non-halal. For buyers, the practical effect is leverage: a certificate from a HAK-accredited body carries the weight of a state-backed competence check, which is why Gulf and Asian import authorities take it seriously.

## The OIC/SMIIC backbone

HAK accredits exclusively against OIC/SMIIC standards — the harmonised rulebook prepared by the Standards and Metrology Institute for Islamic Countries, an OIC affiliate headquartered in Istanbul since its 2010 establishment, now with 46 members plus observers. SMIIC technical committees, open to all member states and deciding by consensus, produce the food, cosmetics, tourism, laboratory and personnel standards HAK works to. Three HAK accreditation schemes exist: bodies certifying halal products and services, bodies certifying the persons who audit and staff the halal industry, and laboratories performing halal testing. Turkiye''s TSE holds HAK accreditation across these tracks, and HAK''s public news record shows accreditations granted to bodies as diverse as GIMDES, South Africa''s SANHA, Australia''s ICCV, New Zealand''s NZIDT, Indonesia''s MUI assessment institute and Japan''s halal association.

## How exporters use HAK-accredited certifiers

Map the product to the right scheme first — most exporters need product certification, while auditors and lab reports flow through the persons and laboratory tracks. Shortlist certifiers from HAK''s accredited-body list rather than the open market, then confirm the chosen body''s accreditation scope covers the product category and the OIC/SMIIC standard edition the destination market expects. Ask the certifier which destination authorities currently accept its certificates and get that in writing; accreditation prestige helps, but destination recognition decides clearance. Keep the HAK accreditation number of the certifier inside the technical file alongside the product certificate — Gulf reviewers increasingly look for the full chain. Confirm current scope with HAK before each season, since accreditations expand, suspend and lapse.

## The mutual-recognition horizon: IFHAB

Accreditation only pays off if foreign markets honour it, which is why HAK has driven the Islamic Forum for Halal Accreditation Bodies (IFHAB): decided at the 2023 OIC foreign-ministers meeting, legislatively grounded through the SMIIC Accreditation Council, and convened for its first General Assembly in Makkah in November 2023. IFHAB is designed as the umbrella under which halal accreditation bodies recognise one another — the mechanism that would one day let a HAK-accredited certificate clear multiple OIC markets without re-audit. It is early days, so treat IFHAB as direction of travel rather than today''s clearance document, and keep destination-by-destination verification as the operating rule.

## HAK versus GIMDES: keep the roles straight

GIMDES is a certifier — one of Turkiye''s largest, HAK-accredited, issuing product certificates to manufacturers. HAK is the accreditor standing above it. An exporter holding a GIMDES certificate answers buyer questions with the certificate; questions about the system behind the certificate point at HAK accreditation. Both facts belong in the export file, and our [verification walkthrough](/verify) shows how to present the chain so a Gulf or Asian reviewer can follow it in minutes.', updated_at=1789500000 WHERE slug='hak-turkey';

UPDATE knowledge_base SET body='Gulf conformity is a parallel system to halal certification, and shipments need both where both apply: halal paperwork proves religious compliance, conformity paperwork proves the product meets technical regulations — confusing them is an expensive error. The framework below untangles the three routes buyers meet most often. For market detail see our [UAE market guide](/market-guides/uae) and [Saudi Arabia market guide](/market-guides/saudi-arabia).

## The G-mark: one mark, six states

The Gulf Conformity Mark (G-mark), governed by the GCC Standardization Organization (GSO), is the region''s shared conformity signal for listed categories — low-voltage electrical equipment and children''s toys carry the priority technical regulations. It is not a quality mark; it declares the product meets the essential health, safety and environmental requirements of the applicable Gulf Technical Regulations. Assessment runs through GSO-approved Notified Bodies, and certified products carry the GSO Conformity Tracking Symbol with its QR code. The payoff is mutual recognition across the six states without re-testing in each. Confirm the current listed categories with GSO before assuming coverage, since the regulation set evolves.

## ECAS: the UAE gate

The Emirates Conformity Assessment Scheme (ECAS), administered by the Ministry of Industry and Advanced Technology (MOIAT), is the UAE''s mandatory product certification for regulated categories spanning electrical goods, machinery, building products, cosmetics and food-contact materials. The route runs through technical-file review, coordinated testing and conformity assessment, with certificates valid one year and renewable before expiry. Above it sits the Emirates Quality Mark (EQM): factory audit plus surveillance on a three-year cycle, mandatory for some categories, and an active EQM can stand in for ECAS at clearance. Every model on the certificate must match the shipped goods and the HS code exactly; generic model numbers are phased out, and mismatches are a leading cause of holds at Jebel Ali and Khalifa ports. See the [MOIAT certifier profile](/certifying-bodies/moiat) for the halal side of the same ministry.

## SABER: the Saudi platform

Saudi Arabia runs conformity through SABER, SASO''s mandatory online platform under the SALEEM product-safety programme. Regulated products register electronically through a SASO-approved conformity body and need a Product Certificate of Conformity (PCoC) followed by a Shipment Certificate of Conformity (SCoC) for each consignment. SASO is the authority writing the technical regulations; SABER is the system where registration and certificates happen — keep the distinction straight when a supplier says vaguely that goods are SASO approved. Consumer products fall under SALEEM procedures inside the platform. Start SABER registration before production ends — PCoC issuance needs test reports that cannot be assembled after stuffing.

## Mutual recognition: what one certificate really unlocks

Recognition in the Gulf is layered, not universal. The G-mark gives the widest automatic carry across the six states but only inside its listed categories. ECAS clears the UAE and informs, but does not replace, Saudi SABER filings — although test reports from recognised labs can often be reused as supporting evidence across both. Halal certificates follow their own recognition logic entirely (SFDA lists, MOIAT accreditation, JAKIM-style mutual recognition), so a product can be conformity-cleared yet halal-blocked, or vice versa. Map each SKU to three separate questions — G-mark applicable, national conformity route, halal route — and diary the three renewal cycles separately, since ECAS, EQM and halal cycles all differ.

## Pre-shipment conformity checks

Fix the destination market and HS code first, then extract the exact requirement list from the authority or an approved body — never from the supplier''s last shipment. Request current test reports and check model numbers, issue dates and reference standards line by line. Approve label and rating-plate artwork, including the G-mark symbol and QR where required, before mass printing. Write conformity responsibility, cost allocation and the payment condition into the contract rather than leaving it to goodwill. And re-verify covered product lists before every season: Gulf technical regulations and national product lists change continuously, and last year''s clear path is not this year''s guarantee.', updated_at=1789500000 WHERE slug='gcc-conformity';

UPDATE knowledge_base SET body='Certificate checks feel like paperwork until a container is held — then they are the whole deal. This checklist turns the seven verification points buyers already know into a pre-shipment routine: what to request, what to compare, and what counts as a fail. Run it before money moves, not after goods sail. Pair it with our [verification walkthrough](/verify) for the portal-by-portal how-to.

## Scope and recognition: the two fatal questions

Ask first which products, categories and facility sites the certificate covers — recognition is frequently category-by-category, so a body approved for meat may not be approved for ingredients or cosmetics. Then ask the sharper question: is the issuing body on the importing authority''s current recognition list for this category. Check JAKIM''s foreign-body list for Malaysia, BPJPH''s overseas-body data for Indonesia, the MUIS recognised-body list for Singapore, SFDA''s approved bodies for Saudi Arabia, and MOIAT registration for the UAE. Verify per market and per category, against the live authority page, on the week of shipment — lists rotate and last quarter''s screenshot proves nothing. A certificate from an unlisted body is not a discount halal certificate; it is no certificate at all.

## Expiry, audits and accreditation depth

Certificates expire — typically after one to three years, with Indonesia allowing extended validity only where ingredients and processes are unchanged. Check the expiry date covers the full shipping and shelf window, and diary both the product certificate and any licensed mark renewals. Behind the certificate, look for surveillance substance: annual audits, corrective-action closure, and ISO/IEC 17065 accreditation of the certifier (or GAC, EIAC or SAAC backing) all signal a living system rather than a one-time audit. Ask the supplier for the most recent surveillance outcome in writing; reluctance to share it is itself information.

## Label review before print

Pull the artwork before anything is printed and match it to the certificate line by line: product name, production site, certifier logo, and validity window must agree exactly. Confirm the destination language rules — Arabic across the Gulf under GSO 9, Bahasa Indonesia for Indonesia, Malay/English practice for Malaysia — with a qualified translator, and check that any licensed mark (Halal National Mark, national logos) is used within its licence terms. Verify nutrition panels support any front-of-pack claims and that date formats survive the logistics chain. One artwork review hour costs a fraction of supervised re-labelling at port.

## CoA, slaughter docs and test evidence

For every high-risk input — gelatin, enzymes, meat derivatives, dairy powders — collect certificates of analysis and supplier halal certificates before the audit, not after. Meat and poultry consignments need slaughter documentation to the destination''s standard: Saudi-bound product requires an Islamic slaughter certificate with government countersignature from the origin country, and strict markets differentiate on stunning and mechanical-slaughter methods, so file the method evidence with the certificate. Where Gulf food-contact rules apply, add migration test reports against GSO 1863/2013 to the file. Keep supplier declarations for all food-contact materials; a missing data sheet draws more auditor attention than an unfamiliar-but-documented chemistry.

## Portal registrations and the document pack

Confirm the shipment''s platform registrations are complete before sailing: SABER Product and Shipment certificates for Saudi Arabia, SIHALAL trails for Indonesia, SFDA e-portal product registration, and Nafeza ACI filing with its ACID number for Egypt. Assemble the export pack as one set — commercial invoice, packing list, bill of lading, certificate of origin, health or veterinary certificates, halal certificate with scope pages, CoAs, label approvals and portal confirmations — and check names, model numbers and batch codes match across every page. Fix certification responsibility and liability for non-compliance in the contract, make conformity a payment condition, and never let the goods sail while a registration is still pending. The cheap outcome is a clean file; the expensive one is a container that teaches the checklist too late.', updated_at=1789500000 WHERE slug='buyers-checklist';

UPDATE knowledge_base SET body='Halal verification starts at official sources and ends at official sources — everything in between is someone''s opinion, including this site. Bookmark the portals below, learn what each one actually verifies, and re-check live before every buying decision, because recognition lists and certificate records rotate continuously. Our [verification walkthrough](/verify) shows the click path; this directory tells you which door to knock on.

## JAKIM: MYeHALAL portal and Verify Halal

Malaysia''s MYeHALAL portal at myehalal.halal.gov.my is the official JAKIM system for halal certification management, combining applications and renewals for businesses with a public verification directory. The public portal lets anyone search certified food premises, packaged products, slaughterhouses, cosmetics, pharmaceuticals and logistics by name, company or state, with each record showing the company entity, address and certificate expiry. JAKIM''s Verify Halal mobile app connects to the same database and adds QR-code scanning for on-premise checks. Since May 2025 all Malaysian halal applications run digitally through MYeHALAL. What it verifies: whether a Malaysian certificate is live, what scope it covers, and whether a foreign certifier is currently recognised. For JAKIM background see the [JAKIM certifier profile](/certifying-bodies/jakim) and our [Malaysia market guide](/market-guides/malaysia).

## BPJPH: SIHALAL and the Indonesian trail

Indonesia certifies through BPJPH''s SIHALAL digital platform, with the applicant portal at ptsp.halal.go.id handling submissions, tracking and the certificate trail. BPJPH''s main site at bpjph.halal.go.id publishes the recognised overseas-body data, fee references and the AI pre-analysis tool buyers meet in newer guidance. What it verifies: the Indonesian certificate behind a national halal logo, and whether a foreign-issued certificate comes from a body BPJPH currently recognises under mutual recognition — category by category. Confirm the current phase and live recognised list with BPJPH on the week of purchase. Context lives in our [Indonesia market guide](/market-guides/indonesia).

## SFDA, MOIAT and MUIS: the Gulf and Singapore gates

Saudi Arabia''s SFDA e-portal handles product registration before shipment — confirm the flow with the local representative, effectively mandatory for smooth clearance. See our [Saudi Arabia market guide](/market-guides/saudi-arabia). The UAE''s MOIAT portal at moiat.gov.ae runs the conformity services behind ECAS certificates and the Halal National Mark licence track; use it to confirm what a UAE conformity or mark claim rests on. See the [MOIAT certifier profile](/certifying-bodies/moiat) and our [UAE market guide](/market-guides/uae). Singapore''s MUIS e-Service at halal.muis.gov.sg lets businesses manage applications and certificates and publishes the certified-establishments, certified-products and recognised-foreign-body lists. What MUIS verifies: whether an establishment or product is currently MUIS-certified and whether a foreign body is recognised for a given scope. See the [MUIS certifier profile](/certifying-bodies/muis).

## Beyond the big five: the portals buyers forget

CICOT runs Thailand''s halal e-services at halal.or.th (new, additional, renewal and cancellation applications) with product verification at halal.co.th and certificate-status checks via its halalthai service — see the [CICOT certifier profile](/certifying-bodies/cicot) and our [Thailand market guide](/market-guides/thailand). Saudi conformity filings live on SABER at saber.sa rather than the SFDA portal — check Product and Shipment certificates there. New Zealand conditions sit in MPI''s password-protected OMARs, Australia''s in DAFF''s MICOR database; both require the supplier''s cooperation to read, so ask for the relevant extract in writing.

## How to use this directory without getting burned

Search the exact legal entity, not the brand shorthand — near-matches mislead. Read the expiry date on every record; a valid-looking listing with a lapsed certificate is a fail. Screenshot and file the live record with the shipment documents, noting the access date. Never accept a supplier''s PDF alone where a public database exists — verify the certificate number, scope and dates independently. And when a portal is down or a record looks inconsistent, contact the authority directly rather than assuming the best; silence from a database is not approval.', updated_at=1789500000 WHERE slug='official-source-directory';

UPDATE knowledge_base SET body='Thailand''s halal mark on an export pack traces to a single authority: the Central Islamic Committee Office of Thailand (CICOT), operating under Halal Affairs Regulations B.E. 2558 (updated B.E. 2568/2025) alongside Thai Agricultural Standard TAS 8400-2025. Certification is voluntary by law but commercially expected — most serious buyers will not take halal-claimed goods without it. For market context see our [Thailand market guide](/market-guides/thailand) and the [CICOT certifier profile](/certifying-bodies/cicot).

## The mark and who stands behind it

CICOT is Thailand''s official halal certification body, working through the central office in Bangkok and the Provincial Islamic Committee Offices for local establishments, with the Halal Science Center supporting the system from the laboratory side. The CICOT halal mark — often referenced as the HAL-TH mark, though buyers should confirm current mark nomenclature with CICOT — is licensed per product, not per company, and its use follows CICOT logo-use requirements. Thailand reports more than 200,000 certified halal items and USD 4.872B in halal food exports to OIC members in Jan–Oct 2025. Export relevance is confirmed multilaterally too — MPI''s June 2026 approved-body list records New Zealand certifiers specifically approved by CICOT for the Thai market, and several Australian AIOs publish CICOT approvals.

## The application route step by step

Preparation comes first: exporters align ingredients, production processes and documentation with the halal standard, often with a consultant, and complete the halal training CICOT''s institute organises. The application goes to CICOT (or the provincial office) with the mark application form, company registration, factory and food-production licences (Or.2), formula registrations (Or.17/Or.18), production-method and raw-material documents, product samples, a site map and the establishment''s halal manual — incomplete files get a short window for correction, so completeness at submission saves weeks. After fee payment CICOT schedules the inspection, typically within one to two weeks; deficiencies carry a correction period before committee approval. Build the file around traceability from the start — certified parties must maintain production-date, location, expiry, labelling and certificate-number traceability throughout.

## E-services: the digital front door

CICOT''s e-services portal at halal.or.th handles the full certificate lifecycle online: new applications, additional-product requests, renewals and cancellations, with trader registration and login. Certificate-status verification runs through its halalthai checking service, while halal.co.th hosts the searchable Thai halal product database — enter a product name or CICOT.HL. certificate number to pull the manufacturer record and its effective-until date. The product database shows multi-year validity horizons on live records, a useful cross-check against the paper certificate in hand.

## Validity schemes and renewal discipline

CICOT operates scheme-dependent validity — commonly discussed as two-year and three-year tracks — so confirm which scheme and duration applies to the product category before budgeting and diary management. Renewal applications must go in before expiry; a lapsed certificate means re-application rather than a simple extension, with fee and timeline consequences. Adding new product items mid-cycle is a separate prescribed request, not an automatic extension of the existing certificate. Because the Thai FDA factory licence and product registrations sit underneath the halal layer, diary those renewals alongside the halal dates — a valid halal mark over an expired food licence still fails a buyer audit.

## Export relevance: why foreign suppliers certify to CICOT

CICOT certification travels: it is accepted across Southeast Asian buyer networks and recognised by international bodies including US certifiers, which is why exporters targeting Thailand — and manufacturers using Thailand as an ASEAN production base — certify locally rather than relying solely on home-country paperwork. Meat and poultry exporters should confirm establishment approval with the Thai importer in parallel. Thai-language labelling per Thai FDA rules applies underneath, so artwork and certification should be prepared as one package. Verify the CICOT certificate number in the public database before ordering, and run the file through our [verification walkthrough](/verify).', updated_at=1789500000 WHERE slug='cicot-thailand';
